import type { AssetPort, LoadedAsset } from '../assets/port';
import { validateAssetBytes } from '../assets/validate-bytes';
import { prepareVerifiedSource } from '../assets/verified-source';
import type { ResidentAssets } from './resident';

/** content/manifest.json: which file holds each asset ID. Generated by scripts/build-playground.mjs. */
export interface PlaygroundManifest {
  design: string;
  assets: Record<string, { file: string; name: string }>;
  resident: ResidentAssets;
}

const hex = (buffer: ArrayBuffer) => [...new Uint8Array(buffer)].map((b) => b.toString(16).padStart(2, '0')).join('');

/**
 * The Playground's AssetPort: files fetched from this site. Even our own files take the same road
 * as an extension import — the ID must be the bytes' SHA-256, and inspectAsset plus the texture
 * and frame checks run before any renderer sees them.
 */
export function createFetchAssets(base: URL, manifest: PlaygroundManifest): AssetPort {
  const cache = new Map<string, Promise<LoadedAsset>>();
  const read = async (id: string, signal?: AbortSignal): Promise<LoadedAsset> => {
    const entry = Object.hasOwn(manifest.assets, id) ? manifest.assets[id] : undefined;
    if (!entry || !/^[a-z0-9-]+\.[a-z0-9]+$/.test(entry.file)) throw new Error('素材が見つかりません。');
    const response = await fetch(new URL(entry.file, base), { signal: signal ?? null, credentials: 'omit' });
    if (!response.ok) throw new Error('素材を読み込めませんでした。');
    const bytes = new Uint8Array(await response.arrayBuffer());
    if (`asset-${hex(await crypto.subtle.digest('SHA-256', bytes))}` !== id)
      throw new Error('素材の内容が ID と一致しません。');
    const { info } = await validateAssetBytes(bytes, '');
    const prepared = prepareVerifiedSource(bytes, info.mime);
    const metadata = { ...info, ...prepared.info, id, name: entry.name, byteLength: bytes.length };
    return prepared.modelBuffer
      ? { metadata, modelBuffer: prepared.modelBuffer }
      : { metadata, blob: new Blob([prepared.bytes!], { type: prepared.info.mime }) };
  };
  return {
    load(id, signal) {
      let entry = cache.get(id);
      if (!entry) {
        entry = read(id, signal).catch((error: unknown) => {
          cache.delete(id);
          throw error;
        });
        cache.set(id, entry);
      }
      return entry;
    },
    clear: () => cache.clear(),
  };
}
